function getValue(key,html){
  var rexString = RegExp(`(var|const|let)+${key}=(("|').*?("|'))`,"")
  return String(html).trim().replace(/\s+/g,'').match(rexString)[2].replace(/"|'/g,"")
}

function getObject(key,html){
  var rexString = RegExp(`(var|const|let)+${key}=({.*?})`,"")
  return JSON.parse(String(html).trim().replace(/\s+/g,'').match(rexString)[2])
}

